#!/bin/bash
# Start Cloudflare Tunnels for Next.js and MT5 Bridge

echo "🚀 Starting Cloudflare Tunnels..."
echo ""

# Check if cloudflared is installed
if ! command -v cloudflared &> /dev/null; then
    echo "❌ cloudflared is not installed!"
    echo ""
    echo "Install it with:"
    echo "  brew install cloudflare/cloudflare/cloudflared"
    echo ""
    echo "Or download from: https://developers.cloudflare.com/cloudflare-one/connections/connect-apps/install-and-setup/installation/"
    exit 1
fi

# Check if Next.js is running
if ! lsof -ti:3000 &> /dev/null; then
    echo "⚠️  Warning: Next.js is not running on port 3000"
    echo "   Start it with: npm run dev"
    echo ""
fi

# Check if Bridge is running
if ! lsof -ti:8080 &> /dev/null; then
    echo "⚠️  Warning: MT5 Bridge is not running on port 8080"
    echo "   Start it with: npm run bridge"
    echo ""
fi

# Create logs directory
mkdir -p logs

echo "Starting tunnels..."
echo ""

# Start Next.js tunnel in background
echo "📱 Starting Next.js tunnel (port 3000)..."
cloudflared tunnel --url http://localhost:3000 > logs/cloudflare-app.log 2>&1 &
APP_PID=$!
echo "✅ Next.js tunnel started (PID: $APP_PID)"
echo "📝 Logs: logs/cloudflare-app.log"

# Wait a moment for tunnel to initialize
sleep 2

# Start Bridge tunnel in background
echo "🔗 Starting Bridge tunnel (port 8080)..."
cloudflared tunnel --url http://localhost:8080 > logs/cloudflare-bridge.log 2>&1 &
BRIDGE_PID=$!
echo "✅ Bridge tunnel started (PID: $BRIDGE_PID)"
echo "📝 Logs: logs/cloudflare-bridge.log"

echo ""
echo "⏳ Waiting 5 seconds for tunnels to initialize..."
sleep 5

# Extract URLs from logs
APP_URL=$(grep -o 'https://[^ ]*\.trycloudflare\.com' logs/cloudflare-app.log 2>/dev/null | head -1)
BRIDGE_URL=$(grep -o 'https://[^ ]*\.trycloudflare\.com' logs/cloudflare-bridge.log 2>/dev/null | head -1)

echo ""
echo "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━ runs in background
if [ -n "$APP_URL" ]; then
    echo "📱 Next.js App URL: $APP_URL"
else
    echo "⚠️  Next.js URL not found in logs. Check logs/cloudflare-app.log"
fi

if [ -n "$BRIDGE_URL" ]; then
    echo "🔗 Bridge URL: $BRIDGE_URL"
    echo ""
    echo "💡 Update .env.local:"
    echo "   NEXT_PUBLIC_BRIDGE_URL=$BRIDGE_URL"
    echo ""
    echo "📱 Or use URL parameter on mobile:"
    echo "   $APP_URL/dashboard?bridge_url=$BRIDGE_URL"
else
    echo "⚠️  Bridge URL not found in logs. Check logs/cloudflare-bridge.log"
